-- Banco de objeciones, segunda parte (reporte «Manejo de objeciones en ventas»):
--   · escalar: cuándo el vendedor debe llevar el tema a un arquitecto (tabla «Cuándo escalar» del reporte):
--     regulación, migración y seguridad, y las preguntas técnicas o fuera de catálogo.
--   · categoría «inesperado»: el protocolo para respuestas fuera de catálogo (algo que no vendemos, un número técnico,
--     una pregunta sin respuesta, un cliente molesto, un nuevo decisor).
-- Vuelve a cargar todo objeciones/objeciones.json para que la base y el repo queden iguales.

alter table public.objeciones drop constraint if exists objeciones_categoria_check;
alter table public.objeciones add constraint objeciones_categoria_check check (categoria in ('autoridad', 'contrato', 'evasiva', 'inesperado', 'migracion', 'necesidad', 'precio', 'proveedor', 'regulacion', 'seguridad', 'timing'));
alter table public.objeciones add column if not exists escalar boolean not null default false;

on conflict (id) do update set
  categoria = excluded.categoria, objecion = excluded.objecion, variantes = excluded.variantes, detras = excluded.detras,
  preguntas = excluded.preguntas, di_mejor = excluded.di_mejor, no_decir = excluded.no_decir,
  revisar_legal = excluded.revisar_legal, escalar = excluded.escalar, fuentes = excluded.fuentes, actualizado = now();
